<?php require 'config.php';$s=$pdo->prepare('SELECT c.*,ca.name category FROM cakes c JOIN categories ca ON ca.id=c.category_id WHERE c.id=? AND c.active=1');$s->execute([(int)($_GET['id']??0)]);$c=$s->fetch();if(!$c)exit('Cake not found');?>
<!doctype html><html><head><meta name="viewport" content="width=device-width,initial-scale=1"><link rel="stylesheet" href="style.css"></head><body><div class="wrap"><div class="card"><?php if($c['image']&&file_exists(__DIR__.'/'.$c['image'])):?><img style="width:100%;max-height:330px;object-fit:cover" src="<?=h($c['image'])?>" alt="<?=h($c['name'])?>"><?php else:?><div class="placeholder">🎂</div><?php endif;?><h1><?=h($c['name'])?></h1><p><?=h($c['category'])?> · <?=h($c['flavor'])?> · <?=h($c['occasion'])?></p><p><?=h($c['description'])?></p><p class="price"><?=money($c['price'])?></p><p>Available stock: <?=h($c['stock'])?></p><form method="post" action="cart.php"><input type="hidden" name="cake_id" value="<?=$c['id']?>"><label>Quantity</label><input type="number" name="quantity" min="1" max="<?=max(1,(int)$c['stock'])?>" value="1" required><label>Cake size</label><select name="size"><option>1/2 kg</option><option>1 kg</option><option>2 kg</option><option>Custom</option></select><label>Message on cake</label><input name="message_text" maxlength="180" placeholder="Happy Birthday!"><button>Add to cart</button></form></div></div></body></html>